[
  # Upstream ash_authentication_phoenix 2.17.3 / ash_authentication 4.14.2 vs
  # ash 3.33 on OTP 29+: `Ash.Resource.record()` is only defined when
  # `System.otp_release() < 29` (see deps/ash/lib/ash/resource.ex), but
  # ash_authentication(_phoenix) reference it unconditionally in several
  # @spec/@type declarations. Not fixable from our side (deps/ is
  # regenerated by `mix deps.get`) — this is a known false positive to
  # revisit next time these deps are bumped.
  {"lib/ash_authentication_phoenix/controller.ex", :unknown_type},

  # Upstream gettext 1.0.2 / expo 1.1.1: `Gettext.Backend`'s generated
  # `plural/2` calls `Gettext.Plural.plural/2` with a compiled
  # `Expo.PluralForms` struct; dialyzer flags this as an opaqueness
  # mismatch (`Expo.PluralForms.plural_ast()` treated as opaque at the
  # call site). Only triggered once a locale with a non-default
  # `Plural-Forms` header exists — first hit when the `uk` locale
  # (i18n) was merged; English's default `nplurals=2;
  # plural=(n != 1);` doesn't hit this path. Adding `fr`
  # ("full UI translation") triggers a second, distinct instance of the
  # same underlying issue (`nplurals=2; plural=(n>1);` — a different
  # formula from both `en`'s and `uk`'s) — this file-level (not
  # line-scoped) ignore already covers it too, confirmed live
  # (`Total errors: 3, Skipped: 3, Unnecessary Skips: 0`), no new entry
  # needed. Matches a known upstream report ("Function call without
  # opaqueness type mismatch", elixirforum.com/t/72407) — not fixable
  # from our side, revisit next time gettext/expo are bumped.
  {"lib/app_web/gettext.ex", :call_without_opaque},

  # Upstream umya_spreadsheet_ex 0.7: `UmyaSpreadsheet.add_list_validation/9`
  # passes its optional `String.t() | nil` prompt arguments to a NIF whose
  # @spec wants `String.t()` and, last, `boolean()` — so dialyzer decides
  # the call can't succeed and everything after it in
  # `App.Xlsx.assignments_workbook/1` has no return (and `patch/2` is
  # "never called"). It works (test/app/xlsx_test.exs). Revisit on the
  # next umya_spreadsheet_ex bump.
  {"lib/app/xlsx.ex", :call},
  {"lib/app/xlsx.ex", :no_return},
  {"lib/app/xlsx.ex", :invalid_contract},
  {"lib/app/xlsx.ex", :unused_fun}
]
